    id: number;
    number: number;
    title: string;
    description: string | null;
    state: "open" | "closed";
    /** Open issues and pull requests in it, of the kinds the caller reads. */
    open_issues: number;
    /** Closed issues, and closed or merged pull requests, of the kinds the caller reads. */
