  /** Import a public git repository. Fetches every branch and tag of a public git repository over HTTPS (smart HTTP, protocol version 2) into this repository, which must be empty, checking the objects as a push is checked. Runs in the background; follow it with the get operation. Needs write access. The source URL must be a public https URL: private and internal addresses and this deployment's own hostnames are refused. */
  "imports.create": { input: ImportsCreateInput; output: ImportsCreateOutput };
  /** Get the repository's import. Returns the progress or outcome of the repository's latest import. */
